//   PAGELOADER (nur bei Hard-Reload, nicht bei Barba-Transitions)
// ═══════════════════════════════════════════════════════════

function initPageloader() {
  const loader = document.querySelector('[data-pageloader]');
  if (!loader) return Promise.resolve();

  const bg = loader.querySelector('[data-pageloader-bg]');
  const text1 = loader.querySelector('[data-pageloader-text-1]');
  const text2 = loader.querySelector('[data-pageloader-text-2]');

  if (!text1 || !text2 || !bg) {
    loader.style.display = 'none';
    return Promise.resolve();
  }

  // Body lock damit nichts gescrollt wird
  document.body.classList.add('pageloader-active');
  if (lenis && typeof lenis.stop === 'function') {
    lenis.stop();
  }

  return new Promise((resolve) => {
    const tl = gsap.timeline({
      onComplete: () => {
        loader.classList.add('is-hidden');
        loader.style.display = 'none';
        document.body.classList.remove('pageloader-active');
        if (lenis && typeof lenis.start === 'function') {
          lenis.start();
        }
        resolve();
      }
    });

    // 0.3s Stille am Anfang für Drama
    tl.to({}, { duration: 0.3 });

    // 1. "One Day" rein
    tl.to(text1, {
      opacity: 1,
      filter: 'blur(0px)',
      duration: 1,
      ease: 'power2.out'
    });

    // 2. Hold "One Day"
    tl.to({}, { duration: 0.7 });

    // 3. "One Day" raus
    tl.to(text1, {
      opacity: 0,
      filter: 'blur(20px)',
      duration: 0.5,
      ease: 'power2.in'
    });

    // 4. "Day One" rein (leicht überlappend für smooth switch)
    tl.to(text2, {
      opacity: 1,
      filter: 'blur(0px)',
      duration: 0.8,
      ease: 'power2.out'
    }, '-=0.2');

    // 5. Hold "Day One"
    tl.to({}, { duration: 0.7 });

    // 6. "Day One" raus + Background raus
    tl.to(text2, {
      opacity: 0,
      filter: 'blur(20px)',
      duration: 0.7,
      ease: 'power2.in'
    });

    tl.to(bg, {
      opacity: 0,
      duration: 0.7,
      ease: 'power2.in'
    }, '<'); // gleichzeitig mit Text-Out
  });
}

