function initLenis() {
  if (lenis) return;
  if (!hasLenis) return;

  lenis = new Lenis({
    lerp: 0.165,
    wheelMultiplier: 1.25
  });

  if (hasScrollTrigger) {
    lenis.on('scroll', ScrollTrigger.update);
  }

  gsap.ticker.add((time) => {
    lenis.raf(time * 1000);
  });
  gsap.ticker.lagSmoothing(0);

  // ── Anchor-Link Support (alle Varianten) ──
  document.addEventListener('click', (e) => {
    const link = e.target.closest('a[href]');
    if (!link) return;

    // WICHTIG: Wenn der Klick INNERHALB des Burgers ist → ignorieren
    // Der Burger-Handler übernimmt das (schließt Menu + scrollt dann)
    if (e.target.closest('[data-burger]')) return;

    // NEU: Klick auf Credit-Trigger → ignorieren
    if (e.target.closest('[data-credit-trigger]')) return;

    const href = link.getAttribute('href');
    if (!href) return;

    // Hash extrahieren
    let hash = null;

    if (href.startsWith('#')) {
      hash = href;
    } else {
      try {
        const url = new URL(href, window.location.href);
        const normalizePath = (p) => p.replace(/\/+$/, '') || '/';

        if (normalizePath(url.pathname) === normalizePath(window.location.pathname) && url
          .hash) {
          hash = url.hash;
        }
      } catch (err) {
        return;
      }
    }

    if (!hash || hash === '#' || hash === '#0') return;

    const target = document.querySelector(hash);
    if (!target) return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    lenis.scrollTo(target, { duration: 2 });
  }, true); // capture phase
}

