function initSignatureHandwriting(container = document) {
  // Auf Tablet/Mobile (< 992px) keine Animation, Signaturen bleiben statisch
  if (window.matchMedia('(max-width: 991px)').matches) return;

  const NS = 'http://www.w3.org/2000/svg';
  const triggers = [];
  const handlers = [];

  Object.entries(SIGNATURE_CENTERLINES).forEach(([attr, config]) => {
    const hosts = container.querySelectorAll(`[${attr}]`);
    if (hosts.length === 0) return;

    hosts.forEach((host) => {
      // Schon initialisiert? Skip
      if (host.dataset.signatureInitialized === 'true') return;
      host.dataset.signatureInitialized = 'true';

      const svg = host.tagName.toLowerCase() === 'svg' ? host : host.querySelector('svg');
      if (!svg) {
        console.warn(`[signature] no <svg> inside [${attr}]`);
        return;
      }

      const uid = `hw-${Math.random().toString(36).slice(2, 8)}`;

      // Inhalt in eine maskierte Gruppe umwandeln
      const group = document.createElementNS(NS, 'g');
      group.setAttribute('mask', `url(#${uid}-mask)`);
      Array.prototype.slice.call(svg.childNodes).forEach((node) => {
        if (node.nodeType === 1 && node.tagName.toLowerCase() === 'defs') return;
        group.appendChild(node);
      });

      const defs = document.createElementNS(NS, 'defs');
      const mask = document.createElementNS(NS, 'mask');
      mask.setAttribute('id', `${uid}-mask`);
      mask.setAttribute('maskUnits', 'userSpaceOnUse');
      const vb = (svg.getAttribute('viewBox') || '').split(/[\s,]+/).map(Number);
      if (vb.length === 4) {
        mask.setAttribute('x', vb[0]);
        mask.setAttribute('y', vb[1]);
        mask.setAttribute('width', vb[2]);
        mask.setAttribute('height', vb[3]);
      }

      const stroke = document.createElementNS(NS, 'path');
      stroke.setAttribute('fill', 'none');
      stroke.setAttribute('stroke', '#fff');
      stroke.setAttribute('stroke-width', config.strokeWidth);
      stroke.setAttribute('stroke-linecap', 'round');
      stroke.setAttribute('stroke-linejoin', 'round');
      stroke.setAttribute('d', config.d);
      mask.appendChild(stroke);
      defs.appendChild(mask);

      svg.appendChild(defs);
      svg.appendChild(group);

      // Initial: Centerline komplett "weg"
      const len = stroke.getTotalLength();
      gsap.set(stroke, {
        strokeDasharray: `${len} ${len + 1}`,
        strokeDashoffset: len
      });

      const tl = gsap.timeline({ paused: true }).to(stroke, {
        strokeDashoffset: 0,
        duration: 2.2,
        ease: 'power2.inOut'
      });

      // Mode: scroll = ScrollTrigger / hover = hover auf Parent
      if (config.mode === 'hover') {
        const hoverTarget = config.hoverParent ?
          host.closest(config.hoverParent) :
          svg;

        if (!hoverTarget) {
          console.warn(`[signature] hover parent ${config.hoverParent} not found`);
          return;
        }

        const onEnter = () => tl.play();
        const onLeave = () => tl.reverse();

        hoverTarget.addEventListener('mouseenter', onEnter);
        hoverTarget.addEventListener('mouseleave', onLeave);

        handlers.push({ el: hoverTarget, onEnter, onLeave });
      } else {
        // scroll mode (default)
        const playReveal = () => tl.play();

        const rect = svg.getBoundingClientRect();
        const viewportHeight = window.innerHeight;
        const alreadyInView = rect.top < viewportHeight * 0.8;

        if (alreadyInView) {
          playReveal();
          return;
        }

        const trigger = ScrollTrigger.create({
          trigger: svg,
          start: 'top 80%',
          once: true,
          onEnter: playReveal
        });

        triggers.push(trigger);
      }
    });
  });

  registerCleanup(() => {
    triggers.forEach((t) => t.kill());
    handlers.forEach(({ el, onEnter, onLeave }) => {
      el.removeEventListener('mouseenter', onEnter);
      el.removeEventListener('mouseleave', onLeave);
    });
  });
}

// ═══════════════════════════════════════════════════════════
//   HERO REVEAL (nur bei Hard-Load / once, nicht nach Barba)
// ═══════════════════════════════════════════════════════════

function initHeroReveal(container = document) {
  const headline = container.querySelector('[data-hero-headline]');
  const nav = document.querySelector('[data-hero-nav]'); // Nav außerhalb Barba-Container
  const credit = container.querySelector('[data-hero-credit]');
  const nextrun = container.querySelector('[data-hero-nextrun]');
  const runSvg = container.querySelector('[data-hero-run]');

  // Nichts da? Skip (z.B. auf Subpages) + Marker entfernen
  if (!headline && !nav && !credit && !nextrun && !runSvg) {
    document.documentElement.classList.remove('is-first-load');
    return;
  }

  // ── Alle Elemente initial verstecken mit Blur ──
  const allElements = [headline, nav, credit, nextrun].filter((el) => el !== null);
  gsap.set(allElements, {
    autoAlpha: 0,
    filter: 'blur(20px)',
    willChange: 'filter, opacity',
    force3D: true
  });

  // ── Master-Timeline ──
  const tl = gsap.timeline({
    defaults: { ease: 'power2.out' }
  });

  // PHASE 1: Headline (SVG) als erstes blur-reveal
  if (headline) {
    tl.to(headline, {
      autoAlpha: 1,
      filter: 'blur(0px)',
      duration: 1.4
    }, 0);
  }

  // PHASE 2: Sekundäre Elemente gestaffelt
  if (nav) {
    tl.to(nav, {
      autoAlpha: 1,
      filter: 'blur(0px)',
      duration: 1.2
    }, 0.6);
  }

  if (credit) {
    tl.to(credit, {
      autoAlpha: 1,
      filter: 'blur(0px)',
      duration: 1.2
    }, 0.8);
  }

  if (nextrun) {
    tl.to(nextrun, {
      autoAlpha: 1,
      filter: 'blur(0px)',
      duration: 1.2
    }, 0.9);
  }

  // PHASE 4: Run-Signatur Centerline-Animation (auf allen Geräten)
  let runAnim = null;
  if (runSvg) {
    runAnim = buildStrokeAnimation(runSvg);
    if (runAnim) {
      gsap.set(runSvg, { opacity: 1 });
      tl.call(() => runAnim.tl.play(), null, 0.5);
    }
  }

  // Cleanup
  registerCleanup(() => {
    tl.kill();
    if (runAnim) runAnim.tl.kill();
  });

  // Nach Animation: Marker entfernen + will-change/transform clearen
  // (sonst bleibt Stacking-Context bestehen und Hero-Elemente scheinen durchs Burger-Menu)
  tl.call(() => {
    document.documentElement.classList.remove('is-first-load');
    gsap.set(allElements, { willChange: 'auto', clearProps: 'transform,filter,willChange' });
  });
}

// ═══════════════════════════════════════════════════════════
//   STROKE ANIMATION ON SCROLL (für Run-SVGs außerhalb Hero)
// ═══════════════════════════════════════════════════════════

function initStrokeAnimations(container = document) {
  // Footer-Run-Animation läuft auch auf Tablet/Mobile

  // Alle Stroke-SVGs außer dem Hero-Run (das läuft separat in initHeroReveal beim Hard-Load)
  const allSvgs = container.querySelectorAll('svg[data-stroke-anim]');
  const svgs = Array.from(allSvgs).filter((svg) => {
    // Skip wenn SVG selbst data-hero-run hat
    if (svg.hasAttribute('data-hero-run')) return false;
    // Skip wenn SVG innerhalb eines data-hero-run Containers liegt
    if (svg.closest('[data-hero-run]')) return false;
    return true;
  });

  if (svgs.length === 0) return;

  const triggers = [];
  const timelines = [];

  svgs.forEach((svg) => {
    // Schon initialisiert? Skip (verhindert doppeltes Aufrufen)
    if (svg.dataset.strokeInitialized === 'true') return;
    svg.dataset.strokeInitialized = 'true';

    const built = buildStrokeAnimation(svg);
    if (!built) return;

    timelines.push(built.tl);

    // ScrollTrigger: Start wenn SVG ins Sichtfeld kommt
    const t = ScrollTrigger.create({
      trigger: svg,
      start: 'top 85%',
      once: true,
      onEnter: () => built.tl.play()
    });
    triggers.push(t);
  });

  registerCleanup(() => {
    triggers.forEach((t) => t.kill());
    timelines.forEach((tl) => tl.kill());
  });
}

// ═══════════════════════════════════════════════════════════
//   STROKE ANIMATION BUILDER (vom Kollegen, angepasst für Barba)
// ═══════════════════════════════════════════════════════════

function buildStrokeAnimation(svg) {
  const SVG_NS = 'http://www.w3.org/2000/svg';

  const DEFAULTS = {
    duration: 2,
    ease: 'power2.inOut',
    delay: 0,
    trigger: 'once',
    yoyo: false,
    repeatDelay: 0
  };

  const centerlines = svg.querySelectorAll('[data-stroke-path]');
  const artwork = svg.querySelector('[data-stroke-art]');
  if (!centerlines.length || !artwork) return null;

  const duration = parseFloat(svg.dataset.strokeDuration) || DEFAULTS.duration;
  const ease = svg.dataset.strokeEase || DEFAULTS.ease;
  const delay = parseFloat(svg.dataset.strokeDelay) || DEFAULTS.delay;
  const trigger = svg.dataset.strokeTrigger || DEFAULTS.trigger;
  const yoyo = svg.dataset.strokeYoyo === 'true';
  const repeatDelay = parseFloat(svg.dataset.strokeRepeatDelay) || DEFAULTS.repeatDelay;
  const strokeWidth = parseFloat(svg.dataset.strokeWidth) || 10;

  // Defs holen/erstellen
  let defs = svg.querySelector('defs');
  if (!defs) {
    defs = document.createElementNS(SVG_NS, 'defs');
    svg.insertBefore(defs, svg.firstChild);
  }

  const vb = (svg.getAttribute('viewBox') || '').split(/[\s,]+/).map(parseFloat);
  const maskId = 'sa-mask-' + Math.random().toString(36).slice(2, 8);

  // Maske erstellen
  const mask = document.createElementNS(SVG_NS, 'mask');
  mask.setAttribute('id', maskId);
  mask.setAttribute('maskUnits', 'userSpaceOnUse');
  if (vb.length === 4 && vb.every((n) => isFinite(n))) {
    mask.setAttribute('x', vb[0]);
    mask.setAttribute('y', vb[1]);
    mask.setAttribute('width', vb[2]);
    mask.setAttribute('height', vb[3]);
  }

  // Pro Centerline einen Mask-Path bauen
  const maskPaths = [];
  let totalLen = 0;
  centerlines.forEach((cl) => {
    const p = document.createElementNS(SVG_NS, 'path');
    p.setAttribute('d', cl.getAttribute('d') || '');
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', 'white');
    p.setAttribute('stroke-width', strokeWidth);
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
    mask.appendChild(p);
    const len = p.getTotalLength();
    if (len > 0) {
      maskPaths.push({ el: p, len: len });
      totalLen += len;
    } else {
      // 0-length paths entfernen (sonst Animation stockt)
      p.parentNode.removeChild(p);
    }
  });
  defs.appendChild(mask);

  if (!maskPaths.length) return null;
  artwork.setAttribute('mask', `url(#${maskId})`);

  // Initial: alle Paths unsichtbar (Gap = len+1 verhindert Endcap-Flecken)
  maskPaths.forEach((mp) => {
    gsap.set(mp.el, {
      strokeDasharray: `${mp.len} ${mp.len + 1}`,
      strokeDashoffset: mp.len
    });
  });

  // Timeline bauen
  const paused = trigger !== 'once' && trigger !== 'loop';
  const tl = gsap.timeline({ paused: paused });
  if (delay && trigger !== 'scrub') tl.delay(delay);
  if (trigger === 'loop') {
    tl.repeat(-1);
    if (yoyo) tl.yoyo(true);
    if (repeatDelay) tl.repeatDelay(repeatDelay);
  }

  // Sequential tweens (jeder Path proportional zu seiner Länge)
  maskPaths.forEach((mp) => {
    tl.to(mp.el, {
      strokeDashoffset: 0,
      duration: duration * (mp.len / totalLen),
      ease: ease
    });
  });

  return { tl, maskId, mask, artwork, trigger };
}

// ═══════════════════════════════════════════════════════════
//   SVG ID FIXER (verhindert ID-Konflikte nach Barba-Transitions)
// ═══════════════════════════════════════════════════════════

function fixSvgIds(container = document) {
  const svgs = container.querySelectorAll('svg');

  svgs.forEach((svg) => {
    // Schon gefixt? Skip
    if (svg.dataset.idsFixed === 'true') return;
    svg.dataset.idsFixed = 'true';

    const uniquePrefix = `svg-${Math.random().toString(36).slice(2, 8)}-`;

    // Sammle alle Elemente mit id-Attribut
    const elementsWithId = svg.querySelectorAll('[id]');
    const idMap = {};

    elementsWithId.forEach((el) => {
      const oldId = el.getAttribute('id');
      const newId = uniquePrefix + oldId;
      idMap[oldId] = newId;
      el.setAttribute('id', newId);
    });

    // Update alle Referenzen (fill, stroke, mask, clip-path, etc.)
    const allElements = svg.querySelectorAll('*');
    allElements.forEach((el) => {
      Array.from(el.attributes).forEach((attr) => {
        const value = attr.value;
        // URL-Referenzen wie url(#id) updaten
        Object.entries(idMap).forEach(([oldId, newId]) => {
          if (value.includes(`#${oldId}`)) {
            el.setAttribute(attr.name, value.replace(
              new RegExp(`#${oldId}(?![\\w-])`, 'g'),
              `#${newId}`
            ));
          }
        });
      });
    });
  });
}

// ═══════════════════════════════════════════════════════════
//   DRAW RANDOM UNDERLINE (on hover)
// ═══════════════════════════════════════════════════════════

function initDrawRandomUnderline(container = document) {
  const svgVariants = [
    `<svg width="310" height="40" viewBox="0 0 310 40" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 20.9999C26.7762 16.2245 49.5532 11.5572 71.7979 14.6666C84.9553 16.5057 97.0392 21.8432 109.987 24.3888C116.413 25.6523 123.012 25.5143 129.042 22.6388C135.981 19.3303 142.586 15.1422 150.092 13.3333C156.799 11.7168 161.702 14.6225 167.887 16.8333C181.562 21.7212 194.975 22.6234 209.252 21.3888C224.678 20.0548 239.912 17.991 255.42 18.3055C272.027 18.6422 288.409 18.867 305 17.9999" stroke="currentColor" stroke-width="10" stroke-linecap="round"/></svg>`,
    `<svg width="310" height="40" viewBox="0 0 310 40" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 24.2592C26.233 20.2879 47.7083 16.9968 69.135 13.8421C98.0469 9.5853 128.407 4.02322 158.059 5.14674C172.583 5.69708 187.686 8.66104 201.598 11.9696C207.232 13.3093 215.437 14.9471 220.137 18.3619C224.401 21.4596 220.737 25.6575 217.184 27.6168C208.309 32.5097 197.199 34.281 186.698 34.8486C183.159 35.0399 147.197 36.2657 155.105 26.5837C158.11 22.9053 162.993 20.6229 167.764 18.7924C178.386 14.7164 190.115 12.1115 201.624 10.3984C218.367 7.90626 235.528 7.06127 252.521 7.49276C258.455 7.64343 264.389 7.92791 270.295 8.41825C280.321 9.25056 296 10.8932 305 13.0242" stroke="#E55050" stroke-width="10" stroke-linecap="round"/></svg>`,
    `<svg width="310" height="40" viewBox="0 0 310 40" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 29.5014C9.61174 24.4515 12.9521 17.9873 20.9532 17.5292C23.7742 17.3676 27.0987 17.7897 29.6575 19.0014C33.2644 20.7093 35.6481 24.0004 39.4178 25.5014C48.3911 29.0744 55.7503 25.7731 63.3048 21.0292C67.9902 18.0869 73.7668 16.1366 79.3721 17.8903C85.1682 19.7036 88.2173 26.2464 94.4121 27.2514C102.584 28.5771 107.023 25.5064 113.276 20.6125C119.927 15.4067 128.83 12.3333 137.249 15.0014C141.418 16.3225 143.116 18.7528 146.581 21.0014C149.621 22.9736 152.78 23.6197 156.284 24.2514C165.142 25.8479 172.315 17.5185 179.144 13.5014C184.459 10.3746 191.785 8.74853 195.868 14.5292C199.252 19.3205 205.597 22.9057 211.621 22.5014C215.553 22.2374 220.183 17.8356 222.979 15.5569C225.4 13.5845 227.457 11.1105 230.742 10.5292C232.718 10.1794 234.784 12.9691 236.164 14.0014C238.543 15.7801 240.717 18.4775 243.356 19.8903C249.488 23.1729 255.706 21.2551 261.079 18.0014C266.571 14.6754 270.439 11.5202 277.146 13.6125C280.725 14.7289 283.221 17.209 286.393 19.0014C292.321 22.3517 298.255 22.5014 305 22.5014" stroke="#E55050" stroke-width="10" stroke-linecap="round"/></svg>`,
    `<svg width="310" height="40" viewBox="0 0 310 40" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M17.0039 32.6826C32.2307 32.8412 47.4552 32.8277 62.676 32.8118C67.3044 32.807 96.546 33.0555 104.728 32.0775C113.615 31.0152 104.516 28.3028 102.022 27.2826C89.9573 22.3465 77.3751 19.0254 65.0451 15.0552C57.8987 12.7542 37.2813 8.49399 44.2314 6.10216C50.9667 3.78422 64.2873 5.81914 70.4249 5.96641C105.866 6.81677 141.306 7.58809 176.75 8.59886C217.874 9.77162 258.906 11.0553 300 14.4892" stroke="#E55050" stroke-width="10" stroke-linecap="round"/></svg>`,
    `<svg width="310" height="40" viewBox="0 0 310 40" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M4.99805 20.9998C65.6267 17.4649 126.268 13.845 187.208 12.8887C226.483 12.2723 265.751 13.2796 304.998 13.9998" stroke="currentColor" stroke-width="10" stroke-linecap="round"/></svg>`,
    `<svg width="310" height="40" viewBox="0 0 310 40" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 29.8857C52.3147 26.9322 99.4329 21.6611 146.503 17.1765C151.753 16.6763 157.115 15.9505 162.415 15.6551C163.28 15.6069 165.074 15.4123 164.383 16.4275C161.704 20.3627 157.134 23.7551 153.95 27.4983C153.209 28.3702 148.194 33.4751 150.669 34.6605C153.638 36.0819 163.621 32.6063 165.039 32.2029C178.55 28.3608 191.49 23.5968 204.869 19.5404C231.903 11.3436 259.347 5.83254 288.793 5.12258C294.094 4.99476 299.722 4.82265 305 5.45025" stroke="#E55050" stroke-width="10" stroke-linecap="round"/></svg>`
  ];

  function decorateSVG(svgEl) {
    svgEl.setAttribute('preserveAspectRatio', 'none');
    svgEl.querySelectorAll('path').forEach((path) => {
      path.setAttribute('stroke', 'currentColor');
    });
  }

  let nextIndex = null;

  container.querySelectorAll('[data-draw-line]').forEach((box_container) => {
    const box = box_container.querySelector('[data-draw-line-box]');
    if (!box) return;

    let enterTween = null;
    let leaveTween = null;

    const onEnter = () => {
      if (enterTween && enterTween.isActive()) return;
      if (leaveTween && leaveTween.isActive()) leaveTween.kill();

      if (nextIndex === null) {
        nextIndex = Math.floor(Math.random() * svgVariants.length);
      }

      box.innerHTML = svgVariants[nextIndex];
      const svg = box.querySelector('svg');
      if (svg) {
        decorateSVG(svg);
        const path = svg.querySelector('path');
        if (path) {
          gsap.set(path, { drawSVG: '0%' });
          enterTween = gsap.to(path, {
            duration: 0.5,
            drawSVG: '100%',
            ease: 'power2.inOut',
            onComplete: () => {
              enterTween = null;
            }
          });
        }
      }

      nextIndex = (nextIndex + 1) % svgVariants.length;
    };

    const onLeave = () => {
      const path = box.querySelector('path');
      if (!path) return;

      const playOut = () => {
        if (leaveTween && leaveTween.isActive()) return;
        leaveTween = gsap.to(path, {
          duration: 0.5,
          drawSVG: '100% 100%',
          ease: 'power2.inOut',
          onComplete: () => {
            leaveTween = null;
            box.innerHTML = '';
          }
        });
      };

      if (enterTween && enterTween.isActive()) {
        enterTween.eventCallback('onComplete', playOut);
      } else {
        playOut();
      }
    };

    box_container.addEventListener('mouseenter', onEnter);
    box_container.addEventListener('mouseleave', onLeave);

    registerCleanup(() => {
      box_container.removeEventListener('mouseenter', onEnter);
      box_container.removeEventListener('mouseleave', onLeave);
      if (enterTween) enterTween.kill();
      if (leaveTween) leaveTween.kill();
    });
  });
}

// ═══════════════════════════════════════════════════════════
//   GRAB / GRABBING CURSOR TOGGLE
// ═══════════════════════════════════════════════════════════

function initGrabCursor(container = document) {
  const grabElements = container.querySelectorAll('[data-cursor="grab"]');
  if (grabElements.length === 0) return;

  const handlers = [];

  grabElements.forEach((el) => {
    const onMouseDown = () => el.setAttribute('data-cursor', 'grabbing');
    const onMouseUp = () => el.setAttribute('data-cursor', 'grab');
    const onMouseLeave = () => {
      if (el.getAttribute('data-cursor') === 'grabbing') {
        el.setAttribute('data-cursor', 'grab');
      }
    };

    el.addEventListener('mousedown', onMouseDown);
    el.addEventListener('mouseup', onMouseUp);
    el.addEventListener('mouseleave', onMouseLeave);

    handlers.push({ el, onMouseDown, onMouseUp, onMouseLeave });
  });

  const onGlobalMouseUp = () => {
    document.querySelectorAll('[data-cursor="grabbing"]').forEach((el) => {
      el.setAttribute('data-cursor', 'grab');
    });
  };

  document.addEventListener('mouseup', onGlobalMouseUp);

  registerCleanup(() => {
    handlers.forEach(({ el, onMouseDown, onMouseUp, onMouseLeave }) => {
      el.removeEventListener('mousedown', onMouseDown);
      el.removeEventListener('mouseup', onMouseUp);
      el.removeEventListener('mouseleave', onMouseLeave);
    });
    document.removeEventListener('mouseup', onGlobalMouseUp);
  });
}

// ═══════════════════════════════════════════════════════════
//   CUSTOM CURSOR FOLLOW (nur beim Slider, scale-based)
// ═══════════════════════════════════════════════════════════

function initCursorFollow(container = document) {
  const cursor = document.querySelector('.cursor');
  if (!cursor) return;

  const cursorBg = cursor.querySelector('.cursor_bg');
  if (!cursorBg) return;

  const mm = gsap.matchMedia();
  mm.add('(hover: hover) and (pointer: fine)', () => {
    let mouseX = 0;
    let mouseY = 0;
    let isVisible = false;

    gsap.set(cursor, { opacity: 1, x: 0, y: 0 });
    gsap.set(cursorBg, { scale: 0 });

    const xTo = gsap.quickTo(cursor, 'x', { duration: 0.15, ease: 'power2.out' });
    const yTo = gsap.quickTo(cursor, 'y', { duration: 0.15, ease: 'power2.out' });

    const onMouseMove = (e) => {
      mouseX = e.clientX;
      mouseY = e.clientY;
      xTo(mouseX);
      yTo(mouseY);
    };

    window.addEventListener('mousemove', onMouseMove);

    const grabElements = container.querySelectorAll('[data-cursor="grab"]');
    const handlers = [];

    grabElements.forEach((slider) => {
      const exclusions = slider.querySelectorAll('a, button, [data-cursor="pointer"]');

      const onSliderEnter = () => showCursor();
      const onSliderLeave = () => hideCursor();

      slider.addEventListener('mouseenter', onSliderEnter);
      slider.addEventListener('mouseleave', onSliderLeave);

      handlers.push({ el: slider, type: 'mouseenter', fn: onSliderEnter });
      handlers.push({ el: slider, type: 'mouseleave', fn: onSliderLeave });

      exclusions.forEach((btn) => {
        const onBtnEnter = (e) => {
          e.stopPropagation();
          hideCursor();
        };
        const onBtnLeave = (e) => {
          e.stopPropagation();
          showCursor();
        };
        btn.addEventListener('mouseenter', onBtnEnter);
        btn.addEventListener('mouseleave', onBtnLeave);

        handlers.push({ el: btn, type: 'mouseenter', fn: onBtnEnter });
        handlers.push({ el: btn, type: 'mouseleave', fn: onBtnLeave });
      });
    });

    function showCursor() {
      if (isVisible) return;
      isVisible = true;
      gsap.set(cursor, { x: mouseX, y: mouseY });
      gsap.to(cursorBg, {
        scale: 1,
        duration: 0.4,
        ease: 'back.out(1.7)',
        overwrite: true
      });
    }

    function hideCursor() {
      if (!isVisible) return;
      isVisible = false;
      gsap.to(cursorBg, {
        scale: 0,
        duration: 0.25,
        ease: 'power2.in',
        overwrite: true
      });
    }

    registerCleanup(() => {
      window.removeEventListener('mousemove', onMouseMove);
      handlers.forEach(({ el, type, fn }) => {
        el.removeEventListener(type, fn);
      });
    });
  });
}

// ═══════════════════════════════════════════════════════════
//   CENTERED SLIDER
// ═══════════════════════════════════════════════════════════

function initSliders(container = document) {
  const sliderWrappers = gsap.utils.toArray(container.querySelectorAll(
    '[data-centered-slider="wrapper"]'));
  if (sliderWrappers.length === 0) return;

  sliderWrappers.forEach((sliderWrapper) => {
    const slides = gsap.utils.toArray(sliderWrapper.querySelectorAll(
      '[data-centered-slider="slide"]'));
    const bullets = gsap.utils.toArray(sliderWrapper.querySelectorAll(
      '[data-centered-slider="bullet"]'));
    const prevButton = sliderWrapper.querySelector('[data-centered-slider="prev-button"]');
    const nextButton = sliderWrapper.querySelector('[data-centered-slider="next-button"]');

    let activeElement;
    let activeBullet;
    let currentIndex = 0;
    let autoplay;

    const autoplayEnabled = sliderWrapper.getAttribute('data-slider-autoplay') === 'true';
    const autoplayDuration = autoplayEnabled ?
      parseFloat(sliderWrapper.getAttribute('data-slider-autoplay-duration')) || 0 :
      0;

    slides.forEach((slide, i) => slide.setAttribute('id', `slide-${i}`));

    if (bullets && bullets.length > 0) {
      bullets.forEach((bullet, i) => {
        bullet.setAttribute('aria-controls', `slide-${i}`);
        bullet.setAttribute('aria-selected', i === currentIndex ? 'true' : 'false');
      });
    }

    const loop = horizontalLoop(slides, {
      paused: true,
      draggable: true,
      center: true,
      onChange: (element, index) => {
        currentIndex = index;
        if (activeElement) activeElement.classList.remove('active');
        element.classList.add('active');
        activeElement = element;

        if (bullets && bullets.length > 0) {
          if (activeBullet) activeBullet.classList.remove('active');
          if (bullets[index]) {
            bullets[index].classList.add('active');
            activeBullet = bullets[index];
          }
          bullets.forEach((bullet, i) => {
            bullet.setAttribute('aria-selected', i === index ? 'true' : 'false');
          });
        }
      }
    });

    loop.toIndex(2, { duration: 0.01 });

    function startAutoplay() {
      if (autoplayDuration > 0 && !autoplay) {
        const repeat = () => {
          loop.next({ ease: 'osmo', duration: 0.725 });
          autoplay = gsap.delayedCall(autoplayDuration, repeat);
        };
        autoplay = gsap.delayedCall(autoplayDuration, repeat);
      }
    }

    function stopAutoplay() {
      if (autoplay) {
        autoplay.kill();
        autoplay = null;
      }
    }

    const trigger = ScrollTrigger.create({
      trigger: sliderWrapper,
      start: 'top bottom',
      end: 'bottom top',
      onEnter: startAutoplay,
      onLeave: stopAutoplay,
      onEnterBack: startAutoplay,
      onLeaveBack: stopAutoplay
    });

    const onWrapperEnter = stopAutoplay;
    const onWrapperLeave = () => {
      if (ScrollTrigger.isInViewport(sliderWrapper)) startAutoplay();
    };
    sliderWrapper.addEventListener('mouseenter', onWrapperEnter);
    sliderWrapper.addEventListener('mouseleave', onWrapperLeave);

    const slideHandlers = [];
    slides.forEach((slide, i) => {
      const onClick = () => loop.toIndex(i, { ease: 'osmo', duration: 0.725 });
      slide.addEventListener('click', onClick);
      slideHandlers.push({ slide, onClick });
    });

    const bulletHandlers = [];
    if (bullets && bullets.length > 0) {
      bullets.forEach((bullet, i) => {
        const onClick = () => {
          loop.toIndex(i, { ease: 'osmo', duration: 0.725 });
          if (activeBullet) activeBullet.classList.remove('active');
          bullet.classList.add('active');
          activeBullet = bullet;
          bullets.forEach((b, j) => {
            b.setAttribute('aria-selected', j === i ? 'true' : 'false');
          });
        };
        bullet.addEventListener('click', onClick);
        bulletHandlers.push({ bullet, onClick });
      });
    }

    let onPrev, onNext;
    if (prevButton) {
      onPrev = () => {
        let newIndex = currentIndex - 1;
        if (newIndex < 0) newIndex = slides.length - 1;
        loop.toIndex(newIndex, { ease: 'osmo', duration: 0.725 });
      };
      prevButton.addEventListener('click', onPrev);
    }

    if (nextButton) {
      onNext = () => {
        let newIndex = currentIndex + 1;
        if (newIndex >= slides.length) newIndex = 0;
        loop.toIndex(newIndex, { ease: 'osmo', duration: 0.725 });
      };
      nextButton.addEventListener('click', onNext);
    }

    registerCleanup(() => {
      stopAutoplay();
      trigger.kill();
      sliderWrapper.removeEventListener('mouseenter', onWrapperEnter);
      sliderWrapper.removeEventListener('mouseleave', onWrapperLeave);
      slideHandlers.forEach(({ slide, onClick }) => slide.removeEventListener('click',
        onClick));
      bulletHandlers.forEach(({ bullet, onClick }) => bullet.removeEventListener('click',
        onClick));
      if (prevButton && onPrev) prevButton.removeEventListener('click', onPrev);
      if (nextButton && onNext) nextButton.removeEventListener('click', onNext);
      if (loop && loop.kill) loop.kill();
    });
  });
}

// ═══════════════════════════════════════════════════════════
//   MARQUEE
// ═══════════════════════════════════════════════════════════

function initMarqueeScrollDirection(container = document) {
  const marquees = container.querySelectorAll('[data-marquee-scroll-direction-target]');
  if (marquees.length === 0) return;

  const setupMarquee = (marquee) => {
    const marqueeContent = marquee.querySelector('[data-marquee-collection-target]');
    const marqueeScroll = marquee.querySelector('[data-marquee-scroll-target]');
    if (!marqueeContent || !marqueeScroll) return;

    const {
      marqueeSpeed: speed,
      marqueeDirection: direction,
      marqueeDuplicate: duplicate
    } = marquee.dataset;

    const marqueeSpeedAttr = parseFloat(speed);
    const marqueeDirectionAttr = direction === 'right' ? 1 : -1;
    const duplicateAmount = parseInt(duplicate || 0);
    const speedMultiplier = window.innerWidth < 479 ? 0.25 : window.innerWidth < 991 ? 0.5 : 1;

    if (marquee.dataset.marqueeInitialized === 'true') return;
    marquee.dataset.marqueeInitialized = 'true';

    if (duplicateAmount > 0) {
      const fragment = document.createDocumentFragment();
      for (let i = 0; i < duplicateAmount; i++) {
        fragment.appendChild(marqueeContent.cloneNode(true));
      }
      marqueeScroll.appendChild(fragment);
    }

    const calculateSpeed = () => {
      return marqueeSpeedAttr * (marqueeContent.offsetWidth / window.innerWidth) *
        speedMultiplier;
    };

    const marqueeItems = marquee.querySelectorAll('[data-marquee-collection-target]');

    const animation = gsap.to(marqueeItems, {
      xPercent: -100,
      repeat: -1,
      duration: calculateSpeed(),
      ease: 'linear'
    }).totalProgress(0.5);

    gsap.set(marqueeItems, { xPercent: marqueeDirectionAttr === 1 ? 100 : -100 });
    animation.timeScale(marqueeDirectionAttr);
    animation.play();

    registerCleanup(() => {
      animation.kill();
      marquee.dataset.marqueeInitialized = 'false';
    });
  };

  const startMarquees = () => {
    requestAnimationFrame(() => {
      marquees.forEach(setupMarquee);
    });
  };

  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(startMarquees);
  } else {
    startMarquees();
  }
}

// ═══════════════════════════════════════════════════════════
//   PARALLAX
// ═══════════════════════════════════════════════════════════

function initGlobalParallax(container = document) {
  const mm = gsap.matchMedia();

  mm.add(
    {
      isMobile: '(max-width:479px)',
      isMobileLandscape: '(max-width:767px)',
      isTablet: '(max-width:991px)',
      isDesktop: '(min-width:992px)'
    },
    (context) => {
      const { isMobile, isMobileLandscape, isTablet } = context.conditions;

      const ctx = gsap.context(() => {
        container.querySelectorAll('[data-parallax="trigger"]').forEach((trigger) => {
          const disable = trigger.getAttribute('data-parallax-disable');
          if (
            (disable === 'mobile' && isMobile) ||
            (disable === 'mobileLandscape' && isMobileLandscape) ||
            (disable === 'tablet' && isTablet)
          ) {
            return;
          }

          const target = trigger.querySelector('[data-parallax="target"]') || trigger;
          const direction = trigger.getAttribute('data-parallax-direction') || 'vertical';
          const prop = direction === 'horizontal' ? 'xPercent' : 'yPercent';

          const scrubAttr = trigger.getAttribute('data-parallax-scrub');
          const scrub = scrubAttr ? parseFloat(scrubAttr) : true;

          const startAttr = trigger.getAttribute('data-parallax-start');
          const startVal = startAttr !== null ? parseFloat(startAttr) : 20;

          const endAttr = trigger.getAttribute('data-parallax-end');
          const endVal = endAttr !== null ? parseFloat(endAttr) : -20;

          const scrollStartRaw = trigger.getAttribute('data-parallax-scroll-start') ||
            'top bottom';
          const scrollStart = `clamp(${scrollStartRaw})`;

          const scrollEndRaw = trigger.getAttribute('data-parallax-scroll-end') ||
            'bottom top';
          const scrollEnd = `clamp(${scrollEndRaw})`;

          gsap.fromTo(
            target, {
              [prop]: startVal
            },
            {
              [prop]: endVal,
              ease: 'none',
              scrollTrigger: {
                trigger,
                start: scrollStart,
                end: scrollEnd,
                scrub
              }
            }
          );
        });
      });

      registerCleanup(() => ctx.revert());
      return () => ctx.revert();
    }
  );
}

// ═══════════════════════════════════════════════════════════
//   ARROW SLIDER (Awwwards-Style mit Smart Queueing)
// ═══════════════════════════════════════════════════════════

function initArrowSlider(container = document) {
  const wrapper = container.querySelector('[data-arrow-slider="wrapper"]');
  if (!wrapper) return;

  const images = wrapper.querySelectorAll('[data-arrow-slider="image"]');
  const headings = wrapper.querySelectorAll('[data-arrow-slider="heading"]');
  const buttons = wrapper.querySelectorAll('[data-arrow-slider="button"]');
  const prevBtn = wrapper.querySelector('[data-arrow-slider="prev"]');
  const nextBtn = wrapper.querySelector('[data-arrow-slider="next"]');

  if (images.length === 0 || !prevBtn || !nextBtn) return;

  const totalSlides = images.length;
  let currentIndex = 0;
  let isAnimating = false;
  let queuedDelta = 0;

  const outDuration = 1.0;
  const inDuration = 1.2;
  const textOutDuration = 0.9;
  const textInDuration = 1.1;
  const overlapRatio = 0.85;
  const buttonOffset = 0.08;
  const charStagger = 0.025;
  const charStaggerOut = 0.015;

  const splitHeadings = [];
  headings.forEach((heading) => {
    const split = SplitText.create(heading, { type: 'chars', mask: 'chars' });
    splitHeadings.push(split);
  });

  function initSlides() {
    images.forEach((img, i) => {
      gsap.set(img, {
        xPercent: i === 0 ? 0 : 100,
        scale: i === 0 ? 1 : 1.05
      });
    });

    headings.forEach((h, i) => {
      gsap.set(h, { yPercent: 0 });
      const chars = splitHeadings[i].chars;
      gsap.set(chars, { yPercent: i === 0 ? 0 : 110 });
    });

    buttons.forEach((b, i) => {
      gsap.set(b, { yPercent: i === 0 ? 0 : 110 });
    });
  }

  function goToSlide(newIndex) {
    isAnimating = true;
    wrapper.classList.add('is-animating');

    while (newIndex < 0) newIndex += totalSlides;
    newIndex = newIndex % totalSlides;

    if (newIndex === currentIndex) {
      isAnimating = false;
      wrapper.classList.remove('is-animating');
      checkQueue();
      return;
    }

    const currentImg = images[currentIndex];
    const nextImg = images[newIndex];
    const currentHeadingChars = splitHeadings[currentIndex].chars;
    const nextHeadingChars = splitHeadings[newIndex].chars;
    const currentButton = buttons[currentIndex];
    const nextButton = buttons[newIndex];

    const currentHeadingCount = currentHeadingChars.length;
    const outTotalDuration = textOutDuration + (currentHeadingCount * charStaggerOut);
    const inStart = outTotalDuration * overlapRatio;

    const tl = gsap.timeline({
      defaults: { ease: 'slider-smooth' },
      onComplete: () => {
        isAnimating = false;
        wrapper.classList.remove('is-animating');
        currentIndex = newIndex;
        checkQueue();
      }
    });

    tl.to(currentImg, { xPercent: 100, scale: 1.05, duration: outDuration, ease: 'slider-out' }, 0);
    tl.set(nextImg, { xPercent: 100, scale: 1.05 }, 0);
    tl.to(nextImg, { xPercent: 0, scale: 1, duration: inDuration, ease: 'slider-in' }, inStart);

    tl.to(currentHeadingChars, {
      yPercent: 110,
      duration: textOutDuration,
      ease: 'slider-out',
      stagger: charStaggerOut
    }, 0);
    tl.set(nextHeadingChars, { yPercent: 110 }, 0);
    tl.to(nextHeadingChars, {
      yPercent: 0,
      duration: textInDuration,
      ease: 'slider-in',
      stagger: charStagger
    }, inStart);

    tl.to(currentButton, { yPercent: 110, duration: textOutDuration, ease: 'slider-out' },
      buttonOffset);
    tl.set(nextButton, { yPercent: 110 }, 0);
    tl.to(nextButton, { yPercent: 0, duration: textInDuration, ease: 'slider-in' }, inStart +
      buttonOffset);
  }

  function checkQueue() {
    if (queuedDelta === 0) return;
    const delta = queuedDelta;
    queuedDelta = 0;
    goToSlide(currentIndex + delta);
  }

  function handleClick(direction) {
    if (isAnimating) {
      queuedDelta += direction;
    } else {
      goToSlide(currentIndex + direction);
    }
  }

  const onNext = () => handleClick(1);
  const onPrev = () => handleClick(-1);

  nextBtn.addEventListener('click', onNext);
  prevBtn.addEventListener('click', onPrev);

  initSlides();

  registerCleanup(() => {
    nextBtn.removeEventListener('click', onNext);
    prevBtn.removeEventListener('click', onPrev);
    splitHeadings.forEach((s) => s.revert());
  });
}

// ═══════════════════════════════════════════════════════════
//   SLIDER ARROW HOVER (Awwwards-style)
// ═══════════════════════════════════════════════════════════

function initSliderArrowHover(container = document) {
  const arrows = container.querySelectorAll('.slider-button');
  if (arrows.length === 0) return;

  const mm = gsap.matchMedia();
  mm.add('(hover: hover) and (pointer: fine)', () => {
    const handlers = [];

    arrows.forEach((arrow) => {
      gsap.set(arrow, {
        backdropFilter: 'blur(25px)',
        borderWidth: '0px',
        borderStyle: 'solid',
        borderColor: 'rgba(255, 255, 255, 0)',
        scale: 1
      });

      const tl = gsap.timeline({ paused: true });

      tl.to(arrow, { backdropFilter: 'blur(0px)', duration: 0.5, ease: 'arrow-blur' }, 0);
      tl.to(arrow, {
        borderColor: 'rgba(255, 255, 255, 0.3)',
        duration: 0.5,
        ease: 'arrow-in'
      }, 0);
      tl.to(arrow, { borderWidth: '1px', duration: 0.7, ease: 'arrow-out' }, 0.05);
      tl.to(arrow, { scale: 1.06, duration: 0.7, ease: 'arrow-out' }, 0);

      const onEnter = () => tl.timeScale(1).play();
      const onLeave = () => tl.timeScale(1.4).reverse();

      arrow.addEventListener('mouseenter', onEnter);
      arrow.addEventListener('mouseleave', onLeave);

      handlers.push({ arrow, onEnter, onLeave, tl });
    });

    registerCleanup(() => {
      handlers.forEach(({ arrow, onEnter, onLeave, tl }) => {
        arrow.removeEventListener('mouseenter', onEnter);
        arrow.removeEventListener('mouseleave', onLeave);
        tl.kill();
      });
    });
  });
}

// ═══════════════════════════════════════════════════════════
//   ROUTE LINES DRAW ANIMATION (SVG-Injection + DrawSVG)
// ═══════════════════════════════════════════════════════════

function initRouteDraw(container = document) {
  const svgImages = container.querySelectorAll('img[data-svg-inject]');
  if (svgImages.length === 0) return Promise.resolve();

  const injectionPromises = Array.from(svgImages).map((img) => {
    // Schon injected? → skip
    if (img.dataset.svgInjected === 'true') return Promise.resolve(null);
    img.dataset.svgInjected = 'true';

    return fetch(img.src)
      .then((response) => response.text())
      .then((svgText) => {
        // Element noch im DOM? Falls Barba inzwischen die Page gewechselt hat → skip
        if (!img.parentNode) return null;

        const parser = new DOMParser();
        const svgDoc = parser.parseFromString(svgText, 'image/svg+xml');
        const svgElement = svgDoc.documentElement;

        if (img.className) svgElement.setAttribute('class', img.className);
        if (img.id) svgElement.setAttribute('id', img.id);

        Array.from(img.attributes).forEach((attr) => {
          if (attr.name.startsWith('data-') && attr.name !== 'data-svg-inject') {
            svgElement.setAttribute(attr.name, attr.value);
          }
        });

        svgElement.setAttribute('data-route-svg', '');
        img.parentNode.replaceChild(svgElement, img);

        return svgElement;
      })
      .catch((err) => {
        // Stille Fehler, nur warnen wenn's nicht offensichtlich ein Page-Wechsel ist
        if (img.parentNode) {
          console.warn('SVG inject failed:', img.src, err);
        }
        return null;
      });
  });

  return Promise.all(injectionPromises).then((svgs) => {
    const validSvgs = svgs.filter((s) => s !== null);
    const triggers = [];

    validSvgs.forEach((svg, index) => {
      const paths = svg.querySelectorAll('path');
      if (paths.length === 0) return;

      gsap.set(paths, { drawSVG: '0%' });

      const trigger = ScrollTrigger.create({
        trigger: svg,
        start: 'top 80%',
        once: true,
        onEnter: () => {
          gsap.to(paths, {
            drawSVG: '100%',
            duration: 2,
            ease: 'power2.inOut',
            delay: index * 0.5,
            stagger: paths.length > 1 ? 0.1 : 0
          });
        }
      });

      triggers.push(trigger);
    });

    registerCleanup(() => {
      triggers.forEach((t) => t.kill());
    });

    return validSvgs;
  });
}

// ═══════════════════════════════════════════════════════════
//   FOOTER CTA BLUR REVEAL
// ═══════════════════════════════════════════════════════════

function initFooterCtaReveal(container = document) {
  const ctaHeader = container.querySelector('.footer_cta_header');
  if (!ctaHeader) return;

  const img = ctaHeader.querySelector('img');
  const heading = ctaHeader.querySelector('h1, h2, h3, h4, h5, h6');
  if (!img && !heading) return;

  const elements = [img, heading].filter((el) => el !== null);

  gsap.set(elements, {
    autoAlpha: 0,
    filter: 'blur(20px)',
    willChange: 'filter, opacity',
    force3D: true
  });

  const playReveal = () => {
    const tl = gsap.timeline({ defaults: { ease: 'power2.out' } });
    tl.to(elements, { autoAlpha: 1, duration: 1, stagger: 0.15 }, 0);
    tl.to(elements, { filter: 'blur(0px)', duration: 2.2, stagger: 0.15 }, '<');
  };

  const rect = ctaHeader.getBoundingClientRect();
  const viewportHeight = window.innerHeight;
  const alreadyInView = rect.top < viewportHeight * 0.8;

  if (alreadyInView) {
    playReveal();
    return;
  }

  const trigger = ScrollTrigger.create({
    trigger: ctaHeader,
    start: 'top 80%',
    once: true,
    onEnter: playReveal
  });

  registerCleanup(() => trigger.kill());
}

// ═══════════════════════════════════════════════════════════
//   SITE CREDIT POPUP
// ═══════════════════════════════════════════════════════════

function initSiteCredit(container = document) {
  const trigger = container.querySelector('[data-credit-trigger]');
  const popup = container.querySelector('[data-credit-popup]');
  if (!trigger || !popup) return;

  let isOpen = false;
  let isAnimating = false;
  let openTl = null;
  let closeTl = null;

  function openPopup() {
    if (isAnimating || isOpen) return;
    isAnimating = true;
    isOpen = true;

    popup.classList.add('is-open');

    if (closeTl) closeTl.kill();
    openTl = gsap.to(popup, {
      opacity: 1,
      filter: 'blur(0px)',
      duration: 0.7,
      ease: 'power2.out',
      onComplete: () => { isAnimating = false; }
    });
  }

  function closePopup() {
    if (isAnimating || !isOpen) return;
    isAnimating = true;
    isOpen = false;

    if (openTl) openTl.kill();
    closeTl = gsap.to(popup, {
      opacity: 0,
      filter: 'blur(20px)',
      duration: 0.4,
      ease: 'power2.in',
      onComplete: () => {
        popup.classList.remove('is-open');
        isAnimating = false;
      }
    });
  }

  const onTriggerClick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (isOpen) {
      closePopup();
    } else {
      openPopup();
    }
  };

  trigger.addEventListener('click', onTriggerClick);

  // ESC-Taste schließt
  const onKeyDown = (e) => {
    if (e.key === 'Escape' && isOpen) {
      closePopup();
    }
  };
  document.addEventListener('keydown', onKeyDown);

  // Click-Outside schließt
  const onDocumentClick = (e) => {
    if (!isOpen) return;
    // Klick innerhalb des Popups oder auf den Trigger → nicht schließen
    if (e.target.closest('[data-credit-popup]')) return;
    if (e.target.closest('[data-credit-trigger]')) return;
    closePopup();
  };
  document.addEventListener('click', onDocumentClick);

  registerCleanup(() => {
    trigger.removeEventListener('click', onTriggerClick);
    document.removeEventListener('keydown', onKeyDown);
    document.removeEventListener('click', onDocumentClick);
    if (openTl) openTl.kill();
    if (closeTl) closeTl.kill();
  });
}

// ═══════════════════════════════════════════════════════════
//   MOBILE MENU
// ═══════════════════════════════════════════════════════════

function initMobileMenu(container = document) {
  // Toggle und Burger global suchen (Nav ist außerhalb Barba-Container)
  const toggle = document.querySelector('[data-burger-toggle]');
  const burger = document.querySelector('[data-burger]');
  if (!toggle || !burger) return;

  // Guard: verhindern dass die Funktion mehrfach initialisiert
  if (toggle.dataset.burgerInitialized === 'true') return;
  toggle.dataset.burgerInitialized = 'true';

  const bg = burger.querySelector('[data-burger-bg]');
  const lineTop = toggle.querySelector('[data-burger-line="top"]');
  const lineBottom = toggle.querySelector('[data-burger-line="bottom"]');
  const links = burger.querySelectorAll('[data-burger-link]');
  const footer = burger.querySelector('.burger_footer');
  const logo = burger.querySelector('.burger_logo');

  if (!bg || !lineTop || !lineBottom || links.length === 0) return;

  // SplitText für jeden Link
  const splitLinks = [];
  const linkTexts = burger.querySelectorAll('.burger_item_text');
  linkTexts.forEach((text) => {
    const split = SplitText.create(text, { type: 'chars', mask: 'chars' });
    splitLinks.push(split);
  });

  // Initial-State
  gsap.set(bg, { opacity: 0 });
  splitLinks.forEach((split) => {
    gsap.set(split.chars, { yPercent: 110 });
  });

  let isOpen = false;
  let isAnimating = false;
  let openTl = null;
  let closeTl = null;

  // ══════════════ OPEN ══════════════
  function openMenu() {
    if (isAnimating || isOpen) return;
    isAnimating = true;
    isOpen = true;

    document.body.classList.add('burger-open');

    if (lenis && typeof lenis.stop === 'function') {
      lenis.stop();
    }

    if (closeTl) closeTl.kill();
    openTl = gsap.timeline({
      defaults: { ease: 'power2.out' },
      onComplete: () => { isAnimating = false; }
    });

    openTl.to(bg, { opacity: 1, duration: 0.5 }, 0);

    const iconHeight = lineBottom.parentElement.offsetHeight;
    const lineHeight = lineTop.offsetHeight;
    const moveDistance = (iconHeight - lineHeight) / 2;

    openTl.to(lineTop, {
      y: moveDistance,
      rotation: 45,
      duration: 0.5,
      ease: 'power2.inOut'
    }, 0.1);

    openTl.to(lineBottom, {
      y: -moveDistance,
      rotation: -45,
      duration: 0.5,
      ease: 'power2.inOut'
    }, 0.1);

    if (logo) {
      openTl.to(logo, {
        opacity: 1,
        filter: 'blur(0px)',
        duration: 1,
        ease: 'power2.out'
      }, 0.2);
    }

    openTl.to(links, {
      opacity: 1,
      filter: 'blur(0px)',
      duration: 1.2,
      stagger: 0.08,
      ease: 'power2.out'
    }, 0.3);

    splitLinks.forEach((split, i) => {
      openTl.to(split.chars, {
        yPercent: 0,
        duration: 0.9,
        ease: 'slider-in',
        stagger: 0.025
      }, 0.3 + i * 0.08);
    });

    if (footer) {
      openTl.to(footer, {
        opacity: 1,
        filter: 'blur(0px)',
        duration: 1,
        ease: 'power2.out'
      }, 0.7);
    }
  }

  // ══════════════ CLOSE ══════════════
  function closeMenu(onCloseComplete) {
    if (isAnimating || !isOpen) {
      if (onCloseComplete) onCloseComplete();
      return;
    }
    isAnimating = true;
    isOpen = false;

    if (openTl) openTl.kill();
    closeTl = gsap.timeline({
      defaults: { ease: 'power2.in' },
      onComplete: () => {
        document.body.classList.remove('burger-open');
        if (lenis && typeof lenis.start === 'function') {
          lenis.start();
        }
        isAnimating = false;
        isOpen = false;
        if (onCloseComplete) onCloseComplete();
      }
    });

    if (logo) {
      closeTl.to(logo, {
        opacity: 0,
        filter: 'blur(20px)',
        duration: 0.4
      }, 0);
    }

    if (footer) {
      closeTl.to(footer, {
        opacity: 0,
        filter: 'blur(20px)',
        duration: 0.4
      }, 0);
    }

    splitLinks.forEach((split, i) => {
      closeTl.to(split.chars, {
        yPercent: 110,
        duration: 0.4,
        ease: 'slider-out',
        stagger: 0.015
      }, i * 0.03);
    });

    closeTl.to(links, {
      opacity: 0,
      filter: 'blur(20px)',
      duration: 0.4
    }, 0.1);

    closeTl.to(lineTop, {
      y: 0,
      rotation: 0,
      duration: 0.5,
      ease: 'power2.inOut'
    }, 0.2);

    closeTl.to(lineBottom, {
      y: 0,
      rotation: 0,
      duration: 0.5,
      ease: 'power2.inOut'
    }, 0.2);

    closeTl.to(bg, {
      opacity: 0,
      duration: 0.4
    }, 0.4);
  }

  // ══════════════ EVENT HANDLERS ══════════════

  const onToggleClick = (e) => {
    e.preventDefault();
    if (isOpen) {
      closeMenu();
    } else {
      openMenu();
    }
  };

  toggle.addEventListener('click', onToggleClick);

  const onKeyDown = (e) => {
    if (e.key === 'Escape' && isOpen) {
      closeMenu();
    }
  };
  document.addEventListener('keydown', onKeyDown);

  // Klick auf einen Link schließt Menu — auch für Anchor-Links
  const onBurgerClick = (e) => {
    const link = e.target.closest('a');
    if (!link) return;
    if (!isOpen) return;

    const href = link.getAttribute('href');
    if (!href) return;

    // Prüfen ob's ein Anchor-Link ist
    let isAnchor = false;
    let anchorHash = null;

    if (href.startsWith('#')) {
      isAnchor = true;
      anchorHash = href;
    } else {
      try {
        const url = new URL(href, window.location.href);
        const normalizePath = (p) => p.replace(/\/+$/, '') || '/';
        if (normalizePath(url.pathname) === normalizePath(window.location.pathname) && url.hash) {
          isAnchor = true;
          anchorHash = url.hash;
        }
      } catch (err) {
        // do nothing
      }
    }

    if (isAnchor && anchorHash) {
      // Anchor-Link: Menu schließen, dann zum Anker scrollen
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      const target = document.querySelector(anchorHash);
      if (!target) {
        closeMenu();
        return;
      }

      closeMenu(() => {
        requestAnimationFrame(() => {
          if (lenis && typeof lenis.scrollTo === 'function') {
            lenis.scrollTo(target, { duration: 2 });
          } else {
            target.scrollIntoView({ behavior: 'smooth' });
          }
        });
      });
    } else {
      // Normaler Link: Menu einfach schließen, Page-Transition läuft normal
      closeMenu();
    }
  };

  burger.addEventListener('click', onBurgerClick, true);
}

// ═══════════════════════════════════════════════════════════
//   HELPER: horizontalLoop
// ═══════════════════════════════════════════════════════════

function horizontalLoop(items, config) {
  let timeline;
  items = gsap.utils.toArray(items);
  config = config || {};

  gsap.context(() => {
    let onChange = config.onChange,
      lastIndex = 0,
      tl = gsap.timeline({
        repeat: config.repeat,
        onUpdate: onChange && function () {
          let i = tl.closestIndex();
          if (lastIndex !== i) {
            lastIndex = i;
            onChange(items[i], i);
          }
        },
        paused: config.paused,
        defaults: { ease: 'none' },
        onReverseComplete: () => tl.totalTime(tl.rawTime() + tl.duration() * 100)
      }),
      length = items.length,
      startX = items[0].offsetLeft,
      times = [],
      widths = [],
      spaceBefore = [],
      xPercents = [],
      curIndex = 0,
      indexIsDirty = false,
      center = config.center,
      pixelsPerSecond = (config.speed || 1) * 100,
      snap = config.snap === false ? (v) => v : gsap.utils.snap(config.snap || 1),
      timeOffset = 0,
      container = center === true ? items[0].parentNode : gsap.utils.toArray(center)[0] ||
      items[0].parentNode,
      totalWidth,
      getTotalWidth = () => items[length - 1].offsetLeft + xPercents[length - 1] / 100 * widths[
        length - 1] - startX + spaceBefore[0] + items[length - 1].offsetWidth * gsap
      .getProperty(items[length - 1], 'scaleX') + (parseFloat(config.paddingRight) || 0),
      populateWidths = () => {
        let b1 = container.getBoundingClientRect(),
          b2;
        items.forEach((el, i) => {
          widths[i] = parseFloat(gsap.getProperty(el, 'width', 'px'));
          xPercents[i] = snap(parseFloat(gsap.getProperty(el, 'x', 'px')) / widths[i] *
            100 + gsap.getProperty(el, 'xPercent'));
          b2 = el.getBoundingClientRect();
          spaceBefore[i] = b2.left - (i ? b1.right : b1.left);
          b1 = b2;
        });
        gsap.set(items, { xPercent: (i) => xPercents[i] });
        totalWidth = getTotalWidth();
      },
      timeWrap,
      populateOffsets = () => {
        timeOffset = center ? tl.duration() * (container.offsetWidth / 2) / totalWidth : 0;
        center && times.forEach((t, i) => {
          times[i] = timeWrap(tl.labels['label' + i] + tl.duration() * widths[i] / 2 /
            totalWidth - timeOffset);
        });
      },
      getClosest = (values, value, wrap) => {
        let i = values.length,
          closest = 1e10,
          index = 0,
          d;
        while (i--) {
          d = Math.abs(values[i] - value);
          if (d > wrap / 2) d = wrap - d;
          if (d < closest) {
            closest = d;
            index = i;
          }
        }
        return index;
      },
      populateTimeline = () => {
        let i, item, curX, distanceToStart, distanceToLoop;
        tl.clear();
        for (i = 0; i < length; i++) {
          item = items[i];
          curX = xPercents[i] / 100 * widths[i];
          distanceToStart = item.offsetLeft + curX - startX + spaceBefore[0];
          distanceToLoop = distanceToStart + widths[i] * gsap.getProperty(item, 'scaleX');
          tl.to(item, {
              xPercent: snap((curX - distanceToLoop) / widths[i] * 100),
              duration: distanceToLoop / pixelsPerSecond
            }, 0)
            .fromTo(item, {
              xPercent: snap((curX - distanceToLoop + totalWidth) / widths[i] * 100)
            }, {
              xPercent: xPercents[i],
              duration: (curX - distanceToLoop + totalWidth - curX) / pixelsPerSecond,
              immediateRender: false
            }, distanceToLoop / pixelsPerSecond)
            .add('label' + i, distanceToStart / pixelsPerSecond);
          times[i] = distanceToStart / pixelsPerSecond;
        }
        timeWrap = gsap.utils.wrap(0, tl.duration());
      },
      refresh = (deep) => {
        let progress = tl.progress();
        tl.progress(0, true);
        populateWidths();
        deep && populateTimeline();
        populateOffsets();
        deep && tl.draggable ? tl.time(times[curIndex], true) : tl.progress(progress, true);
      },
      onResize = () => refresh(true),
      proxy;

    gsap.set(items, { x: 0 });
    populateWidths();
    populateTimeline();
    populateOffsets();
    window.addEventListener('resize', onResize);

    function toIndex(index, vars) {
      vars = vars || {};
      (Math.abs(index - curIndex) > length / 2) && (index += index > curIndex ? -length :
        length);
      let newIndex = gsap.utils.wrap(0, length, index),
        time = times[newIndex];
      if (time > tl.time() !== index > curIndex && index !== curIndex) {
        time += tl.duration() * (index > curIndex ? 1 : -1);
      }
      if (time < 0 || time > tl.duration()) vars.modifiers = { time: timeWrap };
      curIndex = newIndex;
      vars.overwrite = true;
      gsap.killTweensOf(proxy);
      return vars.duration === 0 ? tl.time(timeWrap(time)) : tl.tweenTo(time, vars);
    }

    tl.toIndex = (index, vars) => toIndex(index, vars);
    tl.closestIndex = (setCurrent) => {
      let index = getClosest(times, tl.time(), tl.duration());
      if (setCurrent) {
        curIndex = index;
        indexIsDirty = false;
      }
      return index;
    };
    tl.current = () => indexIsDirty ? tl.closestIndex(true) : curIndex;
    tl.next = (vars) => toIndex(tl.current() + 1, vars);
    tl.previous = (vars) => toIndex(tl.current() - 1, vars);
    tl.times = times;
    tl.progress(1, true).progress(0, true);

    if (config.reversed) {
      tl.vars.onReverseComplete();
      tl.reverse();
    }

    if (config.draggable && typeof Draggable === 'function') {
      proxy = document.createElement('div');
      let wrap = gsap.utils.wrap(0, 1),
        ratio, startProgress, draggable, lastSnap, initChangeX, wasPlaying,
        align = () => tl.progress(wrap(startProgress + (draggable.startX - draggable.x) *
          ratio)),
        syncIndex = () => tl.closestIndex(true);

      typeof InertiaPlugin === 'undefined' && console.warn(
        'InertiaPlugin required for momentum-based scrolling and snapping. https://greensock.com/club'
      );

      draggable = Draggable.create(proxy, {
        trigger: items[0].parentNode,
        type: 'x',
        onPressInit() {
          let x = this.x;
          gsap.killTweensOf(tl);
          wasPlaying = !tl.paused();
          tl.pause();
          startProgress = tl.progress();
          refresh();
          ratio = 1 / totalWidth;
          initChangeX = (startProgress / -ratio) - x;
          gsap.set(proxy, { x: startProgress / -ratio });
        },
        onDrag: align,
        onThrowUpdate: align,
        overshootTolerance: 0,
        inertia: true,
        snap(value) {
          if (Math.abs(startProgress / -ratio - this.x) < 10) return lastSnap + initChangeX;
          let time = -(value * ratio) * tl.duration(),
            wrappedTime = timeWrap(time),
            snapTime = times[getClosest(times, wrappedTime, tl.duration())],
            dif = snapTime - wrappedTime;
          Math.abs(dif) > tl.duration() / 2 && (dif += dif < 0 ? tl.duration() : -tl
            .duration());
          lastSnap = (time + dif) / tl.duration() / -ratio;
          return lastSnap;
        },
        onRelease() {
          syncIndex();
          draggable.isThrowing && (indexIsDirty = true);
        },
        onThrowComplete: () => {
          syncIndex();
          wasPlaying && tl.play();
        }
      })[0];
      tl.draggable = draggable;
    }

    tl.closestIndex(true);
    lastIndex = curIndex;
    onChange && onChange(items[curIndex], curIndex);
    timeline = tl;

    return () => window.removeEventListener('resize', onResize);
  });

  return timeline;
}

// ═══════════════════════════════════════════════════════════
//   FUNCTION REGISTRY (Osmo Pattern)
// ═══════════════════════════════════════════════════════════

function initOnceFunctions() {
  initLenis();
  if (onceFunctionsInitialized) return;
  onceFunctionsInitialized = true;

  // Mobile Menu: einmal global initialisieren (Nav ist außerhalb Barba-Container)
  if (document.querySelector('[data-burger-toggle]')) {
    initMobileMenu();
  }
}

function initBeforeEnterFunctions(next) {
  nextPage = next || document;

  // Diese Funktionen laufen VOR der Enter-Animation,
  // sodass sie schon "ready" sind wenn die Page reinslidet
  if (has('[data-marquee-scroll-direction-target]')) {
    initMarqueeScrollDirection(nextPage);
  }

  if (has('[data-button]')) {
    initButton(nextPage);
  }
}

function initAfterEnterFunctions(next) {
  nextPage = next || document;

  if (has('[data-accordion]')) initAccordion(nextPage);
  if (has('[data-draw-line]')) initDrawRandomUnderline(nextPage);
  if (has('[data-centered-slider="wrapper"]')) initSliders(nextPage);
  if (has('[data-cursor="grab"]')) initGrabCursor(nextPage);
  if (has('[data-cursor="grab"]')) initCursorFollow(nextPage);
  if (has('[data-arrow-slider="wrapper"]')) initArrowSlider(nextPage);
  if (has('.slider-button')) initSliderArrowHover(nextPage);
  if (has('[data-parallax="trigger"]')) initGlobalParallax(nextPage);
  if (has('img[data-svg-inject]')) initRouteDraw(nextPage);
  if (has('.footer_cta_header')) initFooterCtaReveal(nextPage);
  if (has('[data-credit-trigger]')) initSiteCredit(nextPage);
  if (has('[data-svg-stroke-1], [data-svg-stroke-2], [data-svg-stroke-3], [data-svg-stroke-4]')) {
    initSignatureHandwriting(nextPage);
  }
  if (has('svg[data-stroke-anim]')) initStrokeAnimations(nextPage);

  // Mobile Menu: Nach jeder Page-Transition checken
  // (Guard in initMobileMenu verhindert Doppel-Init falls DOM persistiert)
  if (document.querySelector('[data-burger-toggle]')) {
    initMobileMenu();
  }

  if (hasLenis) lenis.resize();
  if (hasScrollTrigger) ScrollTrigger.refresh();
}

// ═══════════════════════════════════════════════════════════
//   PAGE TRANSITIONS
// ═══════════════════════════════════════════════════════════

function runPageOnceAnimation(next) {
  const tl = gsap.timeline();
  tl.call(() => resetPage(next), null, 0);
  return tl;
}

function runPageLeaveAnimation(current, next) {
  const transitionWrap = document.querySelector('[data-transition-wrap]');
  const transitionDark = transitionWrap?.querySelector('[data-transition-dark]');

  const tl = gsap.timeline({
    onComplete: () => current.remove()
  });

  if (reducedMotion) {
    return tl.set(current, { autoAlpha: 0 });
  }

  if (!transitionWrap || !transitionDark) {
    tl.to(current, { autoAlpha: 0, duration: 0.4 });
    return tl;
  }

  tl.set(transitionWrap, { zIndex: 2 });

  tl.fromTo(transitionDark, { autoAlpha: 0 }, { autoAlpha: 0.8, duration: 1.2, ease: 'parallax' },
    0
  );

  tl.fromTo(current, { y: '0vh' }, { y: '-25vh', duration: 1.2, ease: 'parallax' },
    0
  );

  tl.set(transitionDark, { autoAlpha: 0 });

  return tl;
}

function runPageEnterAnimation(next) {
  const tl = gsap.timeline();

  if (reducedMotion) {
    tl.set(next, { autoAlpha: 1 });
    tl.add('pageReady');
    tl.call(resetPage, [next], 'pageReady');
    return new Promise((resolve) => tl.call(resolve, null, 'pageReady'));
  }

  tl.add('startEnter', 0);
  tl.set(next, { zIndex: 3 });

  tl.fromTo(next, { y: '100vh' }, { y: '0vh', duration: 1.2, clearProps: 'all', ease: 'parallax' },
    'startEnter'
  );

  tl.add('pageReady');
  tl.call(resetPage, [next], 'pageReady');

  return new Promise((resolve) => {
    tl.call(resolve, null, 'pageReady');
  });
}

// ═══════════════════════════════════════════════════════════
//   BARBA HOOKS + INIT
// ═══════════════════════════════════════════════════════════

let pendingAnchor = null; // Für Cross-Page Anchor-Links

barba.hooks.beforeLeave((data) => {
  // ── 1. Mobile Menu sofort schließen falls offen ──
  if (document.body.classList.contains('burger-open')) {
    document.body.classList.remove('burger-open');

    const burger = document.querySelector('[data-burger]');
    if (burger) {
      const bg = burger.querySelector('[data-burger-bg]');
      const logo = burger.querySelector('.burger_logo');
      const footer = burger.querySelector('.burger_footer');
      const links = burger.querySelectorAll('[data-burger-link]');

      if (bg) gsap.set(bg, { opacity: 0 });
      if (logo) gsap.set(logo, { opacity: 0, filter: 'blur(20px)' });
      if (footer) gsap.set(footer, { opacity: 0, filter: 'blur(20px)' });
      if (links.length) {
        gsap.set(links, { opacity: 0, filter: 'blur(20px)' });
      }
    }

    const toggle = document.querySelector('[data-burger-toggle]');
    if (toggle) {
      const lineTop = toggle.querySelector('[data-burger-line="top"]');
      const lineBottom = toggle.querySelector('[data-burger-line="bottom"]');
      if (lineTop) gsap.set(lineTop, { y: 0, rotation: 0 });
      if (lineBottom) gsap.set(lineBottom, { y: 0, rotation: 0 });
    }

    // SplitText Chars zurücksetzen
    const linkTexts = document.querySelectorAll('.burger_item_text');
    linkTexts.forEach((text) => {
      const chars = text.querySelectorAll('div, span');
      if (chars.length) gsap.set(chars, { yPercent: 110 });
    });
  }

  // ── 2. Cross-Page Anchor-Link: Hash für nach Transition merken ──
  const nextUrl = data.next?.url?.href;
  if (nextUrl) {
    try {
      const url = new URL(nextUrl);
      if (url.hash) {
        pendingAnchor = url.hash;
      }
    } catch (e) {
      pendingAnchor = null;
    }
  }
});

barba.hooks.beforeEnter((data) => {
  isInTransition = true;

  // ZUERST: SVG-IDs eindeutig machen damit Gradienten/Masken
  // nicht mit der alten Page kollidieren (Safari-Bug)
  fixSvgIds(data.next.container);

  gsap.set(data.next.container, {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0
  });

  if (lenis && typeof lenis.stop === 'function') {
    lenis.stop();
  }

  initBeforeEnterFunctions(data.next.container);
  applyThemeFrom(data.next.container);
});

barba.hooks.afterLeave(() => {
  runPageCleanups();

  if (hasScrollTrigger) {
    ScrollTrigger.getAll().forEach((trigger) => trigger.kill());
  }
});

barba.hooks.enter((data) => {
  initBarbaNavUpdate(data);
});

barba.hooks.afterEnter((data) => {
  isInTransition = false;

  initAfterEnterFunctions(data.next.container);

  if (hasLenis) {
    lenis.resize();
    lenis.start();
  }

  if (hasScrollTrigger) {
    ScrollTrigger.refresh();
  }

  if (window.Webflow) {
    window.Webflow.destroy();
    window.Webflow.ready();
    window.Webflow.require('ix2')?.init();
  }
});

barba.hooks.after(() => {
  // Nach Transition: zum Anchor scrollen falls einer gemerkt wurde
  if (pendingAnchor) {
    const hash = pendingAnchor;
    pendingAnchor = null;

    requestAnimationFrame(() => {
      const target = document.querySelector(hash);
      if (target && lenis) {
        lenis.scrollTo(target, { duration: 2 });
      }
    });
  }
});

barba.init({
  debug: true,
  timeout: 7000,
  preventRunning: false,

  prevent: ({ el, href }) => {
    // Wenn der Link kein href hat → ignorieren
    if (!href) return true;

    // Reine Hash-Links (#section) → IMMER ignorieren, Lenis übernimmt
    if (href.startsWith('#')) return true;

    // mailto, tel, etc.
    if (href.startsWith('mailto:') || href.startsWith('tel:')) return true;

    // Download-Links
    if (el.hasAttribute('download')) return true;

    // target="_blank"
    if (el.getAttribute('target') === '_blank') return true;

    // Externe Links und Anchor-Links zur gleichen Page
    try {
      const url = new URL(href, window.location.href);
      if (url.origin !== window.location.origin) return true;

      const normalizePath = (p) => p.replace(/\/+$/, '') || '/';
      if (normalizePath(url.pathname) === normalizePath(window.location.pathname) && url
        .hash) {
        return true;
      }
    } catch (e) {
      return true;
    }

    return false;
  },

  transitions: [
  {
    name: 'default',
    sync: true,

    async once(data) {
      initOnceFunctions();

      // Pageloader nur beim ersten Page-Load (Hard-Reload)
      await initPageloader();

      await runPageOnceAnimation(data.next.container);
      isInTransition = false;
      initBeforeEnterFunctions(data.next.container);
      initAfterEnterFunctions(data.next.container);
      initHeroReveal(data.next.container);
    },

    async leave(data) {
      return runPageLeaveAnimation(data.current.container, data.next.container);
    },

    async enter(data) {
      return runPageEnterAnimation(data.next.container);
    }
  }]
});

// ═══════════════════════════════════════════════════════════
//   CLICK-LOCK DURING TRANSITIONS (verhindert Race-Conditions)
// ═══════════════════════════════════════════════════════════

document.addEventListener('click', (e) => {
  if (!isInTransition) return;

  const link = e.target.closest('a[href]');
  if (!link) return;

  const href = link.getAttribute('href');
  if (!href) return;

  // Reine Anchor-Links erlauben (Lenis, kein Page-Wechsel)
  if (href.startsWith('#')) return;
  if (href.startsWith('mailto:') || href.startsWith('tel:')) return;
  if (link.getAttribute('target') === '_blank') return;
  if (link.hasAttribute('download')) return;

  // Externe Links erlauben
  try {
    const url = new URL(href, window.location.href);
    if (url.origin !== window.location.origin) return;

    // Anchor zur gleichen Page → erlauben (Lenis)
    const normalizePath = (p) => p.replace(/\/+$/, '') || '/';
    if (normalizePath(url.pathname) === normalizePath(window.location.pathname) && url.hash) {
      return;
    }
  } catch (err) {
    return;
  }

  // Interner Page-Link während Transition → blockieren
  e.preventDefault();
  e.stopPropagation();
  e.stopImmediatePropagation();
}, true); // capture phase = ZUERST

// ═══════════════════════════════════════════════════════════
//   SAME-URL CLICK HANDLER (force Barba transition)
// ═══════════════════════════════════════════════════════════

let lastClickTime = 0;

document.addEventListener('click', (e) => {
  const link = e.target.closest('a[href]');
  if (!link) return;

  // NEU: Wenn's der Credit-Trigger ist → ignorieren
  if (link.closest('[data-credit-trigger]') || link.matches('[data-credit-trigger]')) return;

  const href = link.getAttribute('href');
  if (!href) return;

  // Sofort ignorieren: reine Hash-Links
  if (href.startsWith('#')) return;

  // Externe Links, mailto, tel, etc. ignorieren
  if (href.startsWith('mailto:') || href.startsWith('tel:')) return;
  if (link.getAttribute('target') === '_blank') return;
  if (link.hasAttribute('download')) return;

  // Same-Origin Check
  let url;
  try {
    url = new URL(href, window.location.href);
  } catch (err) {
    return;
  }

  if (url.origin !== window.location.origin) return;

  // Pfade normalisieren
  const normalizePath = (p) => p.replace(/\/+$/, '') || '/';
  const linkPath = normalizePath(url.pathname);
  const currentPath = normalizePath(window.location.pathname);

  // Anchor-Links zur gleichen Page → ignorieren (Lenis macht's)
  if (linkPath === currentPath && url.hash) return;

  // Same URL (gleicher Pfad, kein Hash)?
  if (linkPath === currentPath && !url.hash) {
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    const now = Date.now();
    if (now - lastClickTime < 200) return;
    lastClickTime = now;

    if (isInTransition) {
      const waitForTransition = setInterval(() => {
        if (!isInTransition) {
          clearInterval(waitForTransition);
          if (window.barba && barba.go) {
            barba.go(href);
          }
        }
      }, 50);
      setTimeout(() => clearInterval(waitForTransition), 3000);
      return;
    }

    if (window.barba && barba.go) {
      barba.go(href);
    } else {
      window.location.reload();
    }
  }
}, true);

// ═══════════════════════════════════════════════════════════
//   GENERIC + HELPERS
// ═══════════════════════════════════════════════════════════

const themeConfig = {
  light: { nav: 'dark', transition: 'light' },
  dark: { nav: 'light', transition: 'dark' }
};

function applyThemeFrom(container) {
  const pageTheme = container?.dataset?.pageTheme || 'light';
  const config = themeConfig[pageTheme] || themeConfig.light;

  document.body.dataset.pageTheme = pageTheme;
  const transitionEl = document.querySelector('[data-theme-transition]');
  if (transitionEl) {
    transitionEl.dataset.themeTransition = config.transition;
  }

  const nav = document.querySelector('[data-theme-nav]');
  if (nav) {
    nav.dataset.themeNav = config.nav;
  }
}

function resetPage(container) {
  window.scrollTo(0, 0);
  gsap.set(container, { clearProps: 'position,top,left,right' });

  if (hasLenis) {
    lenis.resize();
    lenis.start();
  }
}

function initBarbaNavUpdate(data) {
  const tpl = document.createElement('template');
  tpl.innerHTML = data.next.html.trim();
  const nextNodes = tpl.content.querySelectorAll('[data-barba-update]');
  const currentNodes = document.querySelectorAll('nav [data-barba-update]');

  currentNodes.forEach((curr, index) => {
    const next = nextNodes[index];
    if (!next) return;

    const newStatus = next.getAttribute('aria-current');
    if (newStatus !== null) {
      curr.setAttribute('aria-current', newStatus);
    } else {
      curr.removeAttribute('aria-current');
    }

    const newClassList = next.getAttribute('class') || '';
    curr.setAttribute('class', newClassList);
  });
}


